INSERT INTO `banners` (`id`, `eyebrow`, `title`, `description`, `image`, `cta_label`, `cta_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Precision instruments since 1986', 'Weigh with confidence.', 'Dependable laboratory and industrial weighing systems for the moments where a small difference matters.', '/images/hero-micro-balance.jpg', 'Explore the range', '/products', 0, 1, '2026-09-16 02:37:42', '2026-09-16 02:37:42'),
(2, 'Built for regulated work', 'Make every result count.', 'From micro balances to high-capacity systems, find clear specifications and practical technical support.', '/images/hero-weigh-bridge.jpg', 'View solutions', '/products', 1, 1, '2026-09-16 02:37:42', '2026-09-16 02:37:42'),
(3, 'Technical support that stays useful', 'A better answer starts here.', 'Talk to Aczet engineers about your sample, capacity, environment, or next weighing challenge.', '/images/hero-gold-analyzer.jpg', 'Talk to an engineer', '/contact', 2, 1, '2026-09-16 02:37:42', '2026-09-16 02:37:42');
INSERT INTO `blogs` (`id`, `title`, `slug`, `type`, `summary`, `content`, `author`, `image`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'Understanding Calibration Standards in Pharmaceutical Balances', 'calibration-standards-in-pharmaceutical-balances', 'Blog', 'Explore the critical role of internal motorized calibration and USP Chapter 41 compliance in analytical laboratory weighing.', 'In pharmaceutical manufacturing, accurate weighing is non-negotiable. USP 41 dictates strict limits on minimum sample weights and repeatability...', 'Dr. R. Sharma (Metrology Division)', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=800&q=80', '2026-08-27 04:00:33', '2026-09-01 04:00:33', '2026-09-01 04:00:33'),
(2, 'How Halogen Moisture Analyzers Accelerate Quality Control in Food Processing', 'halogen-moisture-analyzers-quality-control', 'Blog', 'Learn how switching from conventional drying ovens to halogen moisture analyzers reduces test time from hours to minutes.', 'Moisture content directly impacts shelf life, texture, and regulatory compliance in food manufacturing. Halogen heating provides uniform heat distribution...', 'Aczet QC Research Team', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=800&q=80', '2026-08-20 04:00:33', '2026-09-01 04:00:33', '2026-09-01 04:00:33'),
(3, 'Aczet Showcases Next-Gen Micro-Balances at Analytica Global Expo', 'aczet-showcases-next-gen-micro-balances-at-analytica', 'News', 'Aczet announces the commercial rollout of its CM Series ultra-micro analytical balances featuring sub-microgram readability and ISO 17025 compliance.', 'Aczet officially launched its latest generation of high-precision laboratory balances today. Designed for advanced metrology, materials science, and pharmaceutical assaying, the new CM Series brings unprecedented stability and temperature compensation algorithms. Aczet executives emphasized the company\'s continued dedication to ISO compliance and global calibration standards.', 'Aczet Corporate Newsroom', 'https://images.unsplash.com/photo-1507668077129-56e32842fceb?auto=format&fit=crop&w=800&q=80', '2026-09-14 03:44:29', '2026-09-16 03:44:29', '2026-09-16 03:44:29');
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('aczet-industrial-cache-aczet:lan_gateway_geo', 's:2:\"IN\";', 1791289840),
('aczet-industrial-cache-aczet_site_settings_map', 'a:100:{s:9:\"site_name\";s:15:\"Aczet Metrology\";s:12:\"site_tagline\";s:52:\"Precision Metrology & High Accuracy Weighing Systems\";s:19:\"header_topbar_badge\";s:18:\"WORLDWIDE DISPATCH\";s:18:\"header_topbar_text\";s:74:\"ISO 9001:2015 & OIML Certified Metrology Systems | Direct Factory Dispatch\";s:18:\"header_topbar_link\";s:9:\"/products\";s:16:\"header_cta_label\";s:11:\"Request RFQ\";s:15:\"header_cta_link\";s:11:\"/quote-cart\";s:13:\"phone_primary\";s:16:\"+91 22 4141 5555\";s:13:\"phone_support\";s:16:\"+91 22 4141 5500\";s:11:\"email_sales\";s:15:\"sales@aczet.com\";s:13:\"email_support\";s:17:\"support@aczet.com\";s:15:\"whatsapp_number\";s:13:\"+919820000000\";s:13:\"working_hours\";s:40:\"Monday - Friday: 9:00 AM - 6:30 PM (IST)\";s:10:\"address_hq\";s:84:\"Aczet Metrology Pvt. Ltd., 201, Commercial Center, Mumbai 400069, Maharashtra, India\";s:24:\"address_technical_center\";s:71:\"Aczet European Technical Center, Neugasse 29, 8005 Zürich, Switzerland\";s:11:\"address_usa\";s:76:\"Aczet America Inc., 1250 E Business Center Dr, Mount Prospect, IL 60056, USA\";s:16:\"address_thailand\";s:78:\"Aczet Southeast Asia, 88/12 Rama IX Road, Huai Khwang, Bangkok 10310, Thailand\";s:23:\"metric_experience_years\";s:3:\"40+\";s:23:\"metric_experience_label\";s:29:\"Years of Metrology Excellence\";s:22:\"metric_countries_count\";s:3:\"95+\";s:22:\"metric_countries_label\";s:29:\"Worldwide Export Destinations\";s:22:\"metric_installed_units\";s:8:\"150,000+\";s:22:\"metric_installed_label\";s:27:\"Global Active Installations\";s:26:\"metric_calibration_centers\";s:3:\"12+\";s:24:\"metric_calibration_label\";s:27:\"ISO 17025 Certified Centers\";s:14:\"pillar_1_title\";s:24:\"Monobloc EMFR Technology\";s:13:\"pillar_1_desc\";s:116:\"Single-block electromagnetic force restoration sensor delivering nanogram-level repeatability and thermal stability.\";s:14:\"pillar_2_title\";s:28:\"isoCAL Automated Calibration\";s:13:\"pillar_2_desc\";s:104:\"Internal calibration weights trigger automatically based on temperature changes and scheduled intervals.\";s:14:\"pillar_3_title\";s:25:\"21 CFR Part 11 Compliance\";s:13:\"pillar_3_desc\";s:110:\"Integrated audit trail, tamper-proof user management, and electronic signatures for pharmaceutical compliance.\";s:14:\"pillar_4_title\";s:22:\"Universal Connectivity\";s:13:\"pillar_4_desc\";s:105:\"Ethernet, RS232, USB, and Wi-Fi connectivity for direct LIMS, ERP, and precision PLC automation networks.\";s:17:\"footer_about_text\";s:300:\"Aczet has pioneered the future of precision metrology for over 35 years. Engineered with Swiss-grade monobloc load cells and German electromagnetic force restoration technology, our instruments serve pharmaceutical, research, industrial, and precious metals laboratories in over 95 nations worldwide.\";s:16:\"footer_copyright\";s:104:\"© 2026 Aczet Metrology Pvt. Ltd. All Rights Reserved. ISO 9001:2015 & OIML Certified Metrology Systems.\";s:16:\"footer_iso_badge\";s:34:\"ISO 9001:2015 & OIML R76 Certified\";s:15:\"social_linkedin\";s:38:\"https://www.linkedin.com/company/aczet\";s:14:\"social_youtube\";s:39:\"https://www.youtube.com/@aczetmetrology\";s:14:\"social_twitter\";s:35:\"https://twitter.com/aczet_metrology\";s:15:\"social_facebook\";s:39:\"https://www.facebook.com/aczetmetrology\";s:16:\"social_instagram\";s:40:\"https://www.instagram.com/aczetmetrology\";s:18:\"about_hero_heading\";s:11:\"About Aczet\";s:21:\"about_hero_subheading\";s:172:\"Decades of engineering excellence delivering certified precision weighing, analytical instruments, XRF metal analysis, and laser processing technology to global industries.\";s:22:\"about_overview_eyebrow\";s:18:\"Corporate Overview\";s:20:\"about_overview_title\";s:36:\"Precision Engineering. Global Trust.\";s:17:\"about_overview_p1\";s:416:\"Aczet is a premier manufacturer and global supplier of high-precision weighing balances, laboratory instruments, XRF gold testing and coating thickness analyzers, and precision laser systems. Combining German metrological concepts with world-class production capabilities, Aczet equips pharmaceutical laboratories, jewellery manufacturing clusters, universities, and heavy industrial plants with dependable accuracy.\";s:17:\"about_overview_p2\";s:380:\"Our instruments are deployed in over 65 countries, supported by an established international distributor network, dedicated application engineering centers, and ISO/IEC 17025 accredited calibration labs. Whether measuring a fraction of a microgram in formulation research or screening alloy composition in precious metal refineries, Aczet delivers confidence in every measurement.\";s:16:\"about_stat_1_val\";s:3:\"65+\";s:18:\"about_stat_1_label\";s:16:\"Countries Served\";s:16:\"about_stat_1_sub\";s:19:\"Across 5 continents\";s:16:\"about_stat_2_val\";s:4:\"500+\";s:18:\"about_stat_2_label\";s:16:\"Certified Models\";s:16:\"about_stat_2_sub\";s:24:\"Lab & industrial catalog\";s:16:\"about_stat_3_val\";s:5:\"17025\";s:18:\"about_stat_3_label\";s:14:\"ISO Accredited\";s:16:\"about_stat_3_sub\";s:26:\"Traceable calibration labs\";s:16:\"about_stat_4_val\";s:3:\"25+\";s:18:\"about_stat_4_label\";s:16:\"Years Innovation\";s:16:\"about_stat_4_sub\";s:18:\"Patented metrology\";s:22:\"about_trust_card_title\";s:20:\"ISO 17025 Calibrated\";s:21:\"about_trust_card_desc\";s:119:\"All Aczet weighing and metrology systems ship with factory calibration traceable to national & international standards.\";s:20:\"about_trust_card_btn\";s:23:\"View Accreditations →\";s:17:\"tech_hero_heading\";s:14:\"Our Technology\";s:20:\"tech_hero_subheading\";s:191:\"At Aczet, technology is where engineering meets application. Combining precision mechanics, advanced electronics, and intelligent software for laboratory, industrial, and jewellery workflows.\";s:18:\"tech_intro_eyebrow\";s:22:\"Engineering Philosophy\";s:16:\"tech_intro_title\";s:35:\"Where Engineering Meets Application\";s:13:\"tech_intro_p1\";s:178:\"We combine precision engineering, advanced electronics, and intelligent software to develop high-performance solutions serving laboratory, industrial, and jewellery applications.\";s:13:\"tech_intro_p2\";s:365:\"Our technology portfolio brings together specialised solutions designed to address different measurement, analysis, and production requirements. From sub-microgram mass determination in sterile cleanrooms to high-energy non-destructive gold purity screening, each Aczet instrument is conceived to minimize measurement uncertainty and maximize workflow productivity.\";s:17:\"tech_card_1_badge\";s:13:\"Technology 01\";s:17:\"tech_card_1_title\";s:29:\"Precision Weighing Technology\";s:20:\"tech_card_1_subtitle\";s:22:\"Built around accuracy.\";s:16:\"tech_card_1_desc\";s:315:\"Our portfolio includes micro balances, semi micro balances, analytical balances, precision balances, and industrial weighing systems designed for high accuracy measurements. Powered by monobloc electromagnetic force compensation (EMFC), our load cells resist temperature variations and provide rapid settling times.\";s:17:\"tech_card_1_image\";s:39:\"/images/products/micro-balance-real.jpg\";s:17:\"tech_card_1_specs\";s:89:\"Monobloc EMFC Sensor, 0.0001g Readability, isoCAL Internal Adjustment, FDA 21 CFR Part 11\";s:21:\"tech_card_1_link_text\";s:36:\"View Laboratory Balances Catalog →\";s:20:\"tech_card_1_link_url\";s:38:\"/products?category=laboratory-balances\";s:17:\"tech_card_2_badge\";s:13:\"Technology 02\";s:17:\"tech_card_2_title\";s:29:\"XRF Metal Analysis Technology\";s:20:\"tech_card_2_subtitle\";s:32:\"Fast analysis. Reliable insight.\";s:16:\"tech_card_2_desc\";s:325:\"ACZET XRF analyzers provide fast, non-destructive metal analysis for applications including gold purity testing and alloy identification. Equipped with high-resolution Silicon Drift Detectors (SDD) and proportional counters, our instruments accurately detect karatage, trace contaminants, and electroplated coating thickness.\";s:17:\"tech_card_2_image\";s:37:\"/images/products/gold-compact-eco.jpg\";s:17:\"tech_card_2_specs\";s:91:\"Silicon Drift Detector (SDD), Non-Destructive Screening, Karatage Purity, Coating Thickness\";s:21:\"tech_card_2_link_text\";s:39:\"View Gold Testing & XRF Instruments →\";s:20:\"tech_card_2_link_url\";s:35:\"/products?category=jewelry-machines\";s:17:\"tech_card_3_badge\";s:13:\"Technology 03\";s:17:\"tech_card_3_title\";s:26:\"Laser Technology Solutions\";s:20:\"tech_card_3_subtitle\";s:29:\"Precision beyond measurement.\";s:16:\"tech_card_3_desc\";s:326:\"Our laser marking and laser welding systems are designed for high precision engraving, metal marking, and jewellery repair applications. Features include stereomicroscope alignment, high-energy pulse stability, fiber laser sources, and user-friendly software for hallmarking, serial numbers, and micro-welding delicate alloys.\";s:17:\"tech_card_3_image\";s:33:\"/images/products/handheld-xrf.jpg\";s:17:\"tech_card_3_specs\";s:82:\"Fiber Laser Source, Stereomicroscope Optics, High Pulse Energy, Deep Micro-Welding\";s:21:\"tech_card_3_link_text\";s:43:\"Explore Laser Marking & Welding Systems →\";s:20:\"tech_card_3_link_url\";s:38:\"/products?category=industrial-machines\";s:17:\"tech_card_4_badge\";s:13:\"Technology 04\";s:17:\"tech_card_4_title\";s:28:\"Moisture Analysis Technology\";s:20:\"tech_card_4_subtitle\";s:35:\"Measure what cannot always be seen.\";s:16:\"tech_card_4_desc\";s:303:\"ACZET halogen moisture analyzers provide reliable moisture determination across pharmaceutical, food, chemical, and agricultural industries. Utilizing circular halogen quartz heating and real-time thermogravimetric curves, Aczet moisture balances ensure repeatable drying results with 0.001% resolution.\";s:17:\"tech_card_4_image\";s:43:\"/images/products/moisture-analyzer-real.jpg\";s:17:\"tech_card_4_specs\";s:89:\"Circular Halogen Heating, 0.001% Readability, Live Touchscreen Curves, GLP/GMP Compliance\";s:21:\"tech_card_4_link_text\";s:27:\"View Moisture Analyzers →\";s:20:\"tech_card_4_link_url\";s:38:\"/products?category=laboratory-balances\";}', 2106563440);
INSERT INTO `careers` (`id`, `title`, `department`, `location`, `type`, `experience`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Senior Precision Metrology Engineer', 'Research & Development', 'Mumbai Head Office', 'Full-Time', '5+ Years', 'We are seeking an experienced Metrology Engineer to lead design and calibration algorithm development for micro-weighing load cells.', 1, '2026-09-01 04:00:33', '2026-09-01 04:00:33'),
(2, 'International Sales Executive (GCC & Europe Region)', 'Global Business Development', 'Dubai / Remote', 'Full-Time', '3+ Years in B2B Scientific Equipment', 'Expand Aczet distributor networks and manage high-value B2B OEM accounts across GCC and European industrial sectors.', 1, '2026-09-01 04:00:33', '2026-09-01 04:00:33');
INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `image`, `translations`, `parent_id`, `created_at`, `updated_at`) VALUES
(1, 'Laboratory Weighing', 'laboratory-weighing', 'Micro, semi-micro, analytical and precision balances for laboratory weighing from 0.1 microgram to 35,000 grams.', '/images/products/micro-touchscreen.jpg', '{\"ar\": {\"name\": \"موازين تحليلية فائقة الدقة\", \"description\": \"موازين تحليلية عالية الدقة مصممة للأبحاث المخبرية والصناعات الدوائية بدقة قراءة من 0.1 مجم إلى 0.01 مجم.\"}, \"de\": {\"name\": \"Präzisions-Analysenwaagen\", \"description\": \"Hochpräzise Analysenwaagen für Laborforschung und pharmazeutische Anwendungen mit 0,1 mg bis 0,01 mg Ablesbarkeit.\"}, \"es\": {\"name\": \"Balanzas Analíticas de Precisión\", \"description\": \"Balanzas analíticas de alta precisión diseñadas para investigación de laboratorio y farmacéutica con legibilidad de 0.1mg a 0.01mg.\"}, \"fr\": {\"name\": \"Balances Analytiques de Précision\", \"description\": \"Balances analytiques de haute précision conçues pour la recherche en laboratoire et la pharmacie.\"}, \"it\": {\"name\": \"Bilance Analitiche di Precisione\", \"description\": \"Bilance analitiche ad alta precisione per ricerca di laboratorio e applicazioni farmaceutiche.\"}, \"ja\": {\"name\": \"高精度分析天びん\", \"description\": \"研究室や製薬用途向けに設計された、0.1mg〜0.01mgの読取限度を持つ高精度分析天びん。\"}, \"ko\": {\"name\": \"정밀 분석 전자저울\", \"description\": \"실험실 연구 및 제약 분야를 위해 설계된 0.1mg ~ 0.01mg 판독 한도의 고정밀 분석 저울.\"}, \"pt\": {\"name\": \"Balanças Analíticas de Precisão\", \"description\": \"Balanças analíticas de alta precisão para pesquisa laboratorial e indústria farmacêutica.\"}, \"ru\": {\"name\": \"Прецизионные аналитические весы\", \"description\": \"Высокоточные аналитические весы для лабораторных исследований и фармацевтики с дискретностью от 0.1 мг.\"}, \"th\": {\"name\": \"เครื่องชั่งวิเคราะห์ความละเอียดสูง\", \"description\": \"เครื่องชั่งวิเคราะห์ความแม่นยำสูงสำหรับการวิจัยในห้องปฏิบัติการและเภสัชกรรม ความละเอียด 0.1mg ถึง 0.01mg\"}, \"zh\": {\"name\": \"高精度分析天平\", \"description\": \"专为实验室研究和制药应用设计的高精度分析天平，可读性从0.1mg到0.01mg。\"}}', NULL, '2026-09-01 04:00:33', '2026-09-29 21:43:36'),
(2, 'Scales', 'micro-balances', 'Table top, waterproof, counting, bench, medical, crane and price-computing scales for everyday weighing.', '/images/products/table-top-scale.jpg', '{\"ar\": {\"name\": \"موازين ميكرو وشبه ميكرو\", \"description\": \"موازين ميكرو فائقة الدقة بدقة 1 ميكروجرام لوزن النانوجرام في التركيبات الكيميائية الدقيقة.\"}, \"de\": {\"name\": \"Mikro- & Halbmikrowaagen\", \"description\": \"Ultrapräzise Mikrowaagen mit 1 µg Auflösung für Wägungen im Nanogrammbereich in der chemischen Synthese.\"}, \"es\": {\"name\": \"Micro y Semi-Micro Balanzas\", \"description\": \"Microbalanzas de ultra precisión con resolución de 1µg para pesaje a nivel de nanogramos en síntesis química.\"}, \"fr\": {\"name\": \"Micro & Semi-Micro Balances\", \"description\": \"Microbalances de très haute précision avec résolution de 1µg pour pesage nanogramme.\"}, \"it\": {\"name\": \"Micro e Semi-Micro Bilance\", \"description\": \"Microbilance ad altissima precisione con risoluzione di 1µg per pesate nanometriche.\"}, \"ja\": {\"name\": \"マイクロ＆セミマイクロ天びん\", \"description\": \"化学合成におけるナノグラム測定に対応する、分解能1µgの超高精度マイクロ天びん。\"}, \"ko\": {\"name\": \"마이크로 및 세미 마이크로 저울\", \"description\": \"화학 합성에서 나노그램 단위 계량을 지원하는 1µg 분해능의 초정밀 마이크로 저울.\"}, \"pt\": {\"name\": \"Micro e Semi-Micro Balanças\", \"description\": \"Microbalanças de ultra precisão com resolução de 1µg para pesagens em nanogramas.\"}, \"ru\": {\"name\": \"Микро- и полумикровесы\", \"description\": \"Сверхточные микровесы с разрешением 1 мкг для взвешивания нанограммов.\"}, \"th\": {\"name\": \"เครื่องชั่งไมโครและเซมิไมโคร\", \"description\": \"เครื่องชั่งไมโครความเที่ยงตรงสูงพิเศษ ความละเอียด 1µg สำหรับการชั่งระดับนาโนกรัม\"}, \"zh\": {\"name\": \"微量与超微量天平\", \"description\": \"分辨率达1µg的超高精度微量天平，用于化学合成中的纳克级称重。\"}}', NULL, '2026-09-01 04:00:33', '2026-09-16 02:12:34'),
(3, 'Weigh Bridge & Systems', 'moisture-analyzers', 'Road, portable truck, tank and rail weighing systems with capacities from 5 tonnes to 100 tonnes.', '/images/products/weigh-bridge.jpg', '{\"ar\": {\"name\": \"أجهزة تحليل الرطوبة\", \"description\": \"أجهزة تحديد الرطوبة بالهالوجين توفر قياساً سريعاً وموثوقاً لنسبة الرطوبة في العينات الغذائية والصيدلانية.\"}, \"de\": {\"name\": \"Halogen-Feuchtebestimmer\", \"description\": \"Halogen-Feuchtebestimmungsgeräte für schnelle und zuverlässige Feuchtegehaltsmessungen.\"}, \"es\": {\"name\": \"Analizadores de Humedad\", \"description\": \"Instrumentos de determinación de humedad halógena que proporcionan mediciones rápidas y fiables de contenido de humedad.\"}, \"fr\": {\"name\": \"Dessiccateurs Halogènes\", \"description\": \"Instruments de détermination de l\'humidité par halogène rapides et fiables.\"}, \"it\": {\"name\": \"Analizzatori di Umidità Alogeni\", \"description\": \"Strumenti di misura dell\'umidità alogeni per analisi rapide e affidabili.\"}, \"ja\": {\"name\": \"ハロゲン水分計・分析計\", \"description\": \"食品や化学サンプルの水分含有量を迅速かつ正確に測定するハロゲン加熱式水分分析計。\"}, \"ko\": {\"name\": \"할로겐 수분측정기\", \"description\": \"식품, 제약 및 화학 시료의 수분 함량을 빠르고 신뢰성 있게 측정하는 할로겐 수분분석기.\"}, \"pt\": {\"name\": \"Analisadores de Humidade\", \"description\": \"Equipamentos de determinação de humidade por halogéneo rápidos e confiáveis.\"}, \"ru\": {\"name\": \"Галогенные анализаторы влажности\", \"description\": \"Приборы для быстрого и надежного термогравиметрического определения влаги.\"}, \"th\": {\"name\": \"เครื่องวิเคราะห์ความชื้น\", \"description\": \"เครื่องวัดความชื้นระบบฮาโลเจน ให้ผลการวัดปริมาณความชื้นที่รวดเร็วและแม่นยำ\"}, \"zh\": {\"name\": \"卤素水分测定仪\", \"description\": \"卤素加热水分测定仪器，为食品和化工样品提供快速可靠的水分含量分析。\"}}', NULL, '2026-09-01 04:00:33', '2026-09-16 02:12:34'),
(4, 'Jewellery Instruments', 'industrial-scales', 'Gold testing, laser marking, laser welding, engraving, melting and density solutions for jewellery professionals.', '/images/products/gold-compact-eco.jpg', '{\"ar\": {\"name\": \"موازين ومنصات صناعية\", \"description\": \"موازين منصات ثقيلة من الفولاذ المقاوم للصدأ وموازين رافعات مصممة للمصانع والبيئات الصناعية القاسية.\"}, \"de\": {\"name\": \"Industriewaagen & Plattformen\", \"description\": \"Robuste Edelstahl-Plattformwaagen und Kranwaagen für anspruchsvolle Produktionsumgebungen.\"}, \"es\": {\"name\": \"Básculas Industriales\", \"description\": \"Básculas de plataforma de acero inoxidable de alta resistencia para entornos de fabricación exigentes.\"}, \"fr\": {\"name\": \"Balances & Plates-formes Industrielles\", \"description\": \"Balances de plate-forme en acier inoxydable pour environnements industriels exigeants.\"}, \"it\": {\"name\": \"Bilance e Piattaforme Industriali\", \"description\": \"Bilance a piattaforma in acciaio inox per impieghi gravosi in ambienti industriali.\"}, \"ja\": {\"name\": \"産業用プラットフォームスケール\", \"description\": \"過酷な製造現場に対応する頑丈なステンレス製台秤およびプラットフォームスケール。\"}, \"ko\": {\"name\": \"산업용 플랫폼 저울\", \"description\": \"열악한 생산 현장을 위한 고내구성 스테인리스 스틸 플랫폼 저울 및 크레인 저울.\"}, \"pt\": {\"name\": \"Balanças Industriais\", \"description\": \"Balanças de plataforma em aço inoxidável para ambientes industriais exigentes.\"}, \"ru\": {\"name\": \"Промышленные платформенные весы\", \"description\": \"Сверхнадежные весовые платформы из нержавеющей стали для жестких условий производства.\"}, \"th\": {\"name\": \"เครื่องชั่งอุตสาหกรรม\", \"description\": \"แท่นชั่งสแตนเลสสตีลสำหรับงานหนัก ทนทานสูงสำหรับโรงงานอุตสาหกรรม\"}, \"zh\": {\"name\": \"工业称重平台与台秤\", \"description\": \"重型不锈钢平台秤、吊秤和台秤，适用于严苛的工业制造现场。\"}}', NULL, '2026-09-01 04:00:33', '2026-09-16 02:12:34'),
(5, 'Handheld XRF', 'jewelry-balances', 'Portable material, minerals, RoHS and PMI analysis with fast, non-destructive results.', '/images/products/handheld-xrf.jpg', '{\"ar\": {\"name\": \"موازين الذهب والمجوهرات والقيراط\", \"description\": \"موازين قياس قيراط الذهب والألماس المعتمدة قانونياً لخبراء الأحجار الكريمة وصالات المجوهرات ومراكز الفحص.\"}, \"de\": {\"name\": \"Juwelier- & Karatwaagen\", \"description\": \"Zugelassene Karat- und Goldwaagen für Gemmologen, Juweliere und Prüflabore.\"}, \"es\": {\"name\": \"Balanzas de Joyería y Quilates\", \"description\": \"Balanzas de oro y quilates homologadas para gemólogos, joyerías y centros de ensayo.\"}, \"fr\": {\"name\": \"Balances Joaillerie & Carats\", \"description\": \"Balances homologuées pour l\'or et les carats pour gemmologues et bijouteries.\"}, \"it\": {\"name\": \"Bilance per Oreficeria e Carati\", \"description\": \"Bilance per oro e carati omologate per gemmologi, laboratori e gioiellerie.\"}, \"ja\": {\"name\": \"宝飾・カラット・ジュエリー天びん\", \"description\": \"宝石鑑定士、ジュエリーショールーム、貴金属検査機関向けの検定取得済みカラット天びん。\"}, \"ko\": {\"name\": \"귀금속 및 캐럿 다이아몬드 저울\", \"description\": \"보석 감정원, 주얼리 쇼룸 및 분석 센터를 위한 공인 캐럿 및 금 전자저울.\"}, \"pt\": {\"name\": \"Balanças de Ourivesaria e Quilates\", \"description\": \"Balanças aprovadas para ouro e quilates para joalharias e centros de análise.\"}, \"ru\": {\"name\": \"Ювелирные и каратные весы\", \"description\": \"Весы для взвешивания золота, драгоценных камней и каратов с официальной поверкой.\"}, \"th\": {\"name\": \"เครื่องชั่งทองและเพชรพลอยกะรัต\", \"description\": \"เครื่องชั่งกะรัตและทองคำที่ผ่านการรับรอง สำหรับนักอัญมณีศาสตร์และร้านทอง\"}, \"zh\": {\"name\": \"黄金珠宝与克拉天平\", \"description\": \"经权威计检认证的克拉和黄金天平，适用于宝石学家、珠宝展厅和贵金属检验中心。\"}}', NULL, '2026-09-01 04:00:33', '2026-09-16 02:12:34'),
