(50, 'Ultrasonic Milk Analyzers', 'laboratory-instruments-ultrasonic-milk-analyzers', 'Ultrasonic Milk Analyzers by Aczet - High precision and dependable engineering.', 'images/products/ultrasonic-large.jpg', NULL, 44, '2026-09-21 06:17:04', '2026-09-29 23:13:54'),
(51, 'Ultrasonic Probe Sonicator', 'laboratory-instruments-ultrasonic-probe-sonicator', 'Ultrasonic Probe Sonicator by Aczet - High precision and dependable engineering.', 'images/products/ultrasonic-large.jpg', NULL, 44, '2026-09-21 06:17:04', '2026-09-29 23:13:54'),
(52, 'Refractometers', 'laboratory-instruments-refractometers', 'Refractometers by Aczet - High precision and dependable engineering.', 'images/products/ultrasonic-large.jpg', NULL, 44, '2026-09-21 06:17:04', '2026-09-29 23:13:54'),
(53, 'Rotational Viscometer', 'laboratory-instruments-rotational-viscometer', 'Rotational Viscometer by Aczet - High precision and dependable engineering.', 'images/products/ultrasonic-large.jpg', NULL, 44, '2026-09-21 06:17:04', '2026-09-29 23:13:54'),
