INSERT INTO `products` (`id`, `category_id`, `name`, `model_number`, `apn_number`, `slug`, `short_description`, `full_description`, `translations`, `main_image`, `gallery`, `pdf_datasheet`, `pdf_manual`, `pdf_brochure`, `pdf_service_manual`, `price`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'Aczet Semi Micro & Analytical Balance', 'CY-224C', NULL, 'aczet-semi-micro-analytical-balance', 'Fully automatic analytical weighing with built-in calibration for accurate laboratory results.', 'Fully automatic analytical weighing with built-in calibration for accurate laboratory results.', '{\"ar\": {\"name\": \"ميزان تحليلي عالي الدقة Aczet CY 224\", \"full_description\": \"يوفر الميزان التحليلي Aczet CY 224 أعلى درجات الموثوقية في المختبرات والرقابة الدوائية. مزود بتقنية خلايا الوزن الكهرومغناطيسية المتقدمة لسرعة الاستجابة والاستقرار الفائق ضد تقلبات درجات الحرارة.\", \"short_description\": \"سعة 220 جم بدقة 0.0001 جم (0.1 مجم)، معايرة آلية داخلية بمحرك isoCAL، وشاشة بإضاءة خلفية عالية التباين.\"}, \"de\": {\"name\": \"Aczet CY 224 Präzisions-Analysenwaage\", \"full_description\": \"Die Aczet CY 224 Analysenwaage bietet höchste Präzision für pharmazeutische Qualitätskontrolle und Forschungslabore gemäß USP Chapter 41 und GLP/GMP.\", \"short_description\": \"220g Höchstlast mit 0,0001g (0,1mg) Ablesbarkeit, motorisierter interner Selbstkalibrierung (isoCAL) und USB/RS232 Schnittstelle.\"}, \"es\": {\"name\": \"Balanza Analítica de Precisión Aczet CY 224\", \"full_description\": \"La balanza analítica Aczet CY 224 ofrece la máxima fiabilidad metrológica en laboratorios analíticos, control de calidad farmacéutico y síntesis química. Equipada con tecnología de celda de carga de compensación electromagnética (EMFC) para pesajes rápidos y sin deriva.\", \"short_description\": \"Capacidad de 220g con resolución de 0.0001g (0.1mg), calibración motorizada interna automática isoCAL y pantalla gráfica de alto contraste.\"}, \"zh\": {\"name\": \"Aczet CY 224 高精度分析天平\", \"full_description\": \"Aczet CY 224精密分析天平专为制药研发、质量控制及高校实验室打造，具有卓越的重复性与温度漂移自动补偿功能。\", \"short_description\": \"量程220g，可读性0.0001g (0.1mg)，配备电机驱动的全自动内部校准系统(isoCAL)与GLP/GMP合规输出。\"}}', '/images/products/ultra-micro-2.jpg', '[\"images/products/cy224.svg\", \"images/products/cm21.svg\"]', '/docs/datasheet_cy224.pdf', '/docs/manual_cy224.pdf', '/docs/brochure_aczet_2026.pdf', NULL, NULL, 1, 1, '2026-09-01 04:00:33', '2026-09-16 02:10:38'),
(2, 2, 'Aczet CM 21 Ultra Micro Balance', 'CM-21U', NULL, 'aczet-cm-21-ultra-micro-balance', '21g capacity with 0.000001g (1µg) resolution, motorized glass draft shield, and touch screen interface.', 'Engineered for extreme precision in research laboratories, filter weighing, and nanotechnology. The CM 21 features dual glass draft shields, automatic draft shield door opening with infrared sensors, and audit trail support complying with FDA 21 CFR Part 11.', '{\"ar\": {\"name\": \"ميزان ميكرو فائق الحساسية Aczet CM 21\", \"full_description\": \"مصمم خصيصاً لأبحاث النانوجرام الدقيقة، ووزن مرشحات الهواء والجسيمات الدقيقة والمعايرة الكيميائية فائقة الحساسية.\", \"short_description\": \"سعة 21 جم بدقة 0.000001 جم (1 ميكروجرام)، واقي هوائي زجاجي آلي بمحرك وشاشة لمس ملونة 7 بوصة.\"}, \"es\": {\"name\": \"Microbalanza Ultra Precisión Aczet CM 21\", \"full_description\": \"Diseñada para aplicaciones de investigación crítica de nanogramos, pesaje de filtros de partículas y dosificación de sustancias de alto valor.\", \"short_description\": \"Capacidad de 21g con resolución de 0.000001g (1µg), cortavientos motorizado de cristal y pantalla táctil de 7 pulgadas.\"}}', '/images/products/micro-balance-real.jpg', '[\"images/products/cm21.svg\"]', '/docs/datasheet_cy224.pdf', '/docs/manual_cy224.pdf', '/docs/brochure_aczet_2026.pdf', NULL, 7490.00, 1, 1, '2026-09-01 04:00:33', '2026-09-16 02:14:34'),
(3, 3, 'Aczet MB 200 Touchscreen Halogen Moisture Analyzer', 'MB-200T', NULL, 'aczet-mb-200-touchscreen-moisture-analyzer', '200g max capacity, 0.001g moisture readability, 400W halogen heating lamp up to 200°C.', 'Designed for rapid moisture determination in food, pharma, plastics, and chemical samples. Color touchscreen LCD display with real-time drying curve graphs, customizable heating profiles (Standard, Fast, Step, Gentle), and memory for 100 drying programs.', '{\"ar\": {\"name\": \"جهاز تحليل الرطوبة بالهالوجين بشاشة لمس Aczet MB 200\", \"full_description\": \"يحدد نسبة الرطوبة بدقة خلال دقائق في عينات الأغذية والكيماويات والحبوب مع 100 برنامج تخزين للمعايرة.\", \"short_description\": \"سعة 200 جم، دقة رطوبة 0.001 جم / 0.01%، مصباح تسخين هالوجين 400 واط حتى 200 درجة مئوية.\"}, \"es\": {\"name\": \"Analizador de Humedad Halógeno con Pantalla Táctil Aczet MB 200\", \"full_description\": \"Determina el contenido de humedad en cuestión de minutos con perfiles de calentamiento programables y memoria para 100 métodos.\", \"short_description\": \"Capacidad máxima de 200g, legibilidad de humedad del 0.001g / 0.01%, lámpara de calentamiento halógeno de 400W hasta 200°C.\"}}', '/images/products/moisture-analyzer-real.jpg', '[\"images/products/mb200.svg\"]', '/docs/datasheet_cy224.pdf', '/docs/manual_cy224.pdf', '/docs/brochure_aczet_2026.pdf', NULL, 2950.00, 1, 1, '2026-09-01 04:00:33', '2026-09-16 02:14:34'),
(4, 4, 'Aczet Heavy Duty Stainless Platform Scale IP68', 'IS-600S', NULL, 'aczet-heavy-duty-platform-scale-ip68', '600kg capacity, 10g division, washdown IP68 hermetically sealed load cell.', 'Built for food processing and chemical plants. All 304 stainless steel construction with heavy duty diamond plate pan, overload protection up to 150%, battery backup, and high-visibility LED display.', '{\"ar\": {\"name\": \"ميزان منصة صناعي ثقيل Aczet IS 600\", \"full_description\": \"مصمم للاستخدام الشاق في مصانع الكيماويات والصناعات الغذائية والمستودعات والخدمات اللوجستية.\", \"short_description\": \"سعة صناعية 600 كجم، منصة من الفولاذ المقاوم للصدأ 304 مع حماية IP68 ضد الماء والغبار.\"}, \"es\": {\"name\": \"Báscula de Plataforma de Alta Resistencia Aczet IS 600\", \"full_description\": \"Plataforma industrial para plantas de fabricación química, alimentos y logística de almacén.\", \"short_description\": \"Capacidad industrial de 600kg, plataforma de acero inoxidable 304 con protección IP68 y celda de carga de precisión.\"}}', 'images/products/is600.svg', '[\"images/products/is600.svg\"]', '/docs/datasheet_cy224.pdf', '/docs/manual_cy224.pdf', '/docs/brochure_aczet_2026.pdf', NULL, 1200.00, 0, 1, '2026-09-01 04:00:33', '2026-09-01 06:48:00'),
(5, 5, 'Aczet GXZ 600 Diamond & Carat Scale', 'GXZ-600', NULL, 'aczet-gxz-600-diamond-carat-scale', '600ct (120g) capacity with 0.001ct (0.0001g) precision, windshield included.', 'Approved by international weights & measures authorities. Features carat, gram, grain, and troy ounce units. Includes gem bowl, calibration weights, and density determination kit for gemstone verification.', '{\"ar\": {\"name\": \"ميزان الذهب والألماس والقيراط Aczet GXZ 600\", \"full_description\": \"ميزان معتمد لفحص ووزن الألماس والأحجار الكريمة وسبائك الذهب في محلات المجوهرات ومختبرات الدمغ.\", \"short_description\": \"سعة 600 قيراط / 120 جم بدقة 0.001 قيراط، معتمد قانونياً للدمغة وفحص المعادن الثمينة.\"}, \"es\": {\"name\": \"Balanza de Joyería y Quilates Aczet GXZ 600\", \"full_description\": \"Balanza certificada para pesaje de diamantes, gemas preciosas, oro y platino en joyerías y casas de empeño.\", \"short_description\": \"Capacidad de 600ct / 120g con legibilidad de 0.001ct, homologación legal para metrología y ensaye de metales preciosos.\"}}', 'images/products/gxz600.svg', '[\"images/products/gxz600.svg\"]', '/docs/datasheet_cy224.pdf', '/docs/manual_cy224.pdf', '/docs/brochure_aczet_2026.pdf', NULL, 980.00, 0, 1, '2026-09-01 04:00:33', '2026-09-01 06:48:00'),
(6, 2, 'Aczet Touch Screen Micro Balance', 'CM-A', NULL, 'aczet-touch-screen-micro-balance', 'Touch screen micro balance with 22 g capacity, 30 mm pan and 1 microgram readability.', 'Touch screen micro balance with 22 g capacity, 30 mm pan and 1 microgram readability.', NULL, '/images/products/micro-touchscreen.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-09-16 01:59:24', '2026-09-16 02:10:38'),
(7, 2, 'Aczet Table Top Scale', 'TTS-31', NULL, 'aczet-table-top-scale', 'Practical table top weighing from 1 g to 31 kg with LED or LCD display and optional RS-232C.', 'Practical table top weighing from 1 g to 31 kg with LED or LCD display and optional RS-232C.', NULL, '/images/products/table-top-scale.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-09-16 01:59:24', '2026-09-16 02:10:38'),
(8, 3, 'Aczet Weigh Bridge', 'WB-100T', NULL, 'aczet-weigh-bridge', 'Road weigh bridge with 100 tonne capacity, 18 x 3 metre platform and LED display.', 'Road weigh bridge with 100 tonne capacity, 18 x 3 metre platform and LED display.', NULL, '/images/products/weigh-bridge.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-09-16 01:59:24', '2026-09-16 02:10:38'),
(9, 4, 'Aczet Gold Testing Machine (Compact Eco Series)', 'COMPACT-ECO', NULL, 'aczet-gold-testing-machine-compact-eco-series', 'Computerised gold analyser with 50 kV software-controlled X-ray tube and precision collimator.', 'Computerised gold analyser with 50 kV software-controlled X-ray tube and precision collimator.', NULL, '/images/products/gold-compact-eco.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-09-16 01:59:24', '2026-09-16 02:10:38'),
