INSERT INTO `publications` (`id`, `title`, `category`, `summary`, `file`, `translations`, `created_at`, `updated_at`) VALUES
(1, 'USP Chapter 41 & 1251 Compliance in Pharmaceutical Weighing', 'Regulatory Metrology', 'Comprehensive guidance on repeatability determinations and operating ranges for analytical balances.', '/docs/usp41_aczet_guide.pdf', '{\"ar\": {\"title\": \"الامتثال لمعايير دستور الأدوية الأمريكي USP 41 و 1251 في الوزن الصيدلاني\", \"summary\": \"دليل شامل حول تحديد التكرار ونطاقات التشغيل للموازين التحليلية المخبرية.\"}, \"de\": {\"title\": \"USP-Kapitel 41 & 1251 Konformität beim pharmazeutischen Wägen\", \"summary\": \"Umfassender Leitfaden zur Wiederholbarkeitsbestimmung und zu Arbeitsbereichen für Analysenwaagen.\"}, \"es\": {\"title\": \"Cumplimiento de los Capítulos 41 y 1251 de la USP en Pesaje Farmacéutico\", \"summary\": \"Guía completa sobre determinaciones de repetibilidad y rangos operativos para balanzas analíticas.\"}, \"fr\": {\"title\": null, \"summary\": null}, \"it\": {\"title\": null, \"summary\": null}, \"ja\": {\"title\": null, \"summary\": null}, \"ko\": {\"title\": null, \"summary\": null}, \"pt\": {\"title\": null, \"summary\": null}, \"ru\": {\"title\": null, \"summary\": null}, \"th\": {\"title\": null, \"summary\": null}, \"zh\": {\"title\": \"制药称量中的USP第41章和第1251章合规指南\", \"summary\": \"关于分析天平重复性测定和有效操作范围的权威合规技术指南。\"}}', '2026-09-01 04:17:11', '2026-09-01 04:21:12'),
(2, 'Rapid Moisture Determination Using 400W Halogen Radiation', 'Application Note', 'Comparative study of AOAC oven drying versus Aczet MB 200 halogen drying curves in food QA.', '/docs/moisture_application_note.pdf', '{\"ar\": {\"title\": \"التحديد السريع للرطوبة باستخدام إشعاع الهالوجين 400 واط\", \"summary\": \"دراسة مقارنة بين التجفيف في فرن AOAC ومنحنيات التجفيف بالهالوجين Aczet MB 200 في مراقبة جودة الأغذية.\"}, \"es\": {\"title\": \"Determinación Rápida de Humedad Mediante Radiación Halógena de 400W\", \"summary\": \"Estudio comparativo del secado en horno AOAC frente a las curvas de secado halógeno Aczet MB 200.\"}}', '2026-09-01 04:17:11', '2026-09-01 04:17:11'),
(3, 'OIML R76 Class I & II Non-Automatic Weighing Instruments Directive', 'International Standards', 'Technical specifications and legal metrology verification criteria.', '/docs/oiml_r76_standards.pdf', '{\"es\": {\"title\": \"Directiva OIML R76 Clase I y II para Instrumentos de Pesaje de Funcionamiento No Automático\", \"summary\": \"Especificaciones técnicas y criterios de verificación de metrología legal internacional.\"}}', '2026-09-01 04:17:11', '2026-09-01 04:17:11'),
(4, 'MonoTech Electromagnetic Force Compensation Principle', 'Engineering Whitepaper', 'In-depth review of single-block load cell monolithic cut design ensuring sub-milligram stability.', '/docs/monotech_whitepaper.pdf', '{\"es\": {\"title\": \"Principio de Compensación de Fuerza Electromagnética MonoTech\", \"summary\": \"Revisión exhaustiva del diseño de celda de carga de bloque único que garantiza estabilidad submiligramo.\"}}', '2026-09-01 04:17:11', '2026-09-01 04:17:11');
